  display: flex;
  align-items: center;
  gap: 60px;
}

.scroll-rule {
  width: 340px;
  height: 1px;
  background-color: #ddd;
  display: flex;
  justify-content: center;
  align-items: center;
}

.scroll-label {
  width: 100px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.scroll-label img {
