/* MON-05 시작 — height:auto로 1920×1000 원본 이미지 비율을 유지합니다. */
.brand-video img {
  width: 100%;
  height: auto;
  object-fit: cover;
}

/* MON-05 끝 */

/* MON-06 시작 — 각 칸에 box-sizing을 주어 padding 때문에 1400px을 넘지 않게 합니다. */
.information {
  background-color: #f7f7f7;
}

.information-con {
  height: 355px;
}

.news {
