  font-size: 12px;
}

.news-rule {
  width: 100%;
  height: 1px;
  background-color: #ddd;
}

.news-list {
  padding-top: 10px;
}

.news-list li {
  display: flex;
  justify-content: space-between;
  padding-bottom: 5px;
  font-size: 12px;
  color: #888;
}

.info-panel {
  width: 350px;
  padding-top: 65px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.inquiry {
  background: #f5f5f5 url('../image/inquiry-bg.jpg') center top / 350px 355px no-repeat;
}

.shop {
  background: #f5f5f5 url('../image/shop-bg.png') center top / 350px 365px no-repeat;
