  font-size: 12px;
  margin: 30px 0 0;
}

/* MON-06 끝 */

/* MON-07 시작 — 전체 배경과 안쪽 .con의 폭을 분리합니다. */
.footer {
  padding-top: 60px;
  padding-bottom: 65px;
  background-color: #111;
}

.footer-con {
  flex-direction: column;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 25px;
}

.footer-rule {
  width: 100%;
  height: 1px;
  background-color: #292929;
}

.footer-top > img {
  width: 128px;
  height: 32px;
}

.footer-menu {
  display: flex;
  gap: 22px;
  color: #777;
  font-size: 12px;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding-top: 20px;
}

.company-info {
  width: 570px;
}

.footer-bottom h2 {
  font-size: 13px;
  color: #ccc;
  padding-bottom: 12px;
}

.company-info p {
  font-size: 12px;
  color: #555;
  padding-bottom: 5px;
}

.customer-center {
  width: 250px;
}

.customer-center .customer-tel {
  font-size: 24px;
  color: #777;
  padding-bottom: 15px;
}

.kakao-btn {
  width: 155px;
  height: 35px;
  border-radius: 4px;
  background-color: #444;
  color: #bbb;
  font-size: 13px;
}

.family-site {
